import{_ as e,r as i,o as r,c as s,a,b as o,d,e as n}from"./app.ChrdILIc.js";import"./chunks/three-vendor.DK3fmyXa.js";const y=JSON.parse('{"title":"SaaS 介绍与使用","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech-tools/saas.md","filePath":"zh/tech-tools/saas.md","lastUpdated":1778395361000}'),h={name:"zh/tech-tools/saas.md"};function S(u,t,c,f,g,x){const l=i("ArticleMetadata");return r(),s("div",null,[t[0]||(t[0]=a("h1",{id:"saas-介绍与使用",tabindex:"-1"},[o("SaaS 介绍与使用 "),a("a",{class:"header-anchor",href:"#saas-介绍与使用","aria-label":'Permalink to "SaaS 介绍与使用"'},"​")],-1)),d(l),t[1]||(t[1]=n('<p>SaaS 是 <code>Software as a Service</code> 的缩写，中文通常叫“软件即服务”。它指的是用户不需要自己安装、部署和维护软件，而是通过浏览器、客户端或 API 直接使用厂商提供的在线软件服务。</p><p>简单理解：SaaS 不是把软件卖给你让你安装，而是把软件作为持续在线的服务提供给你。</p><h2 id="常见例子" tabindex="-1">常见例子 <a class="header-anchor" href="#常见例子" aria-label="Permalink to &quot;常见例子&quot;">​</a></h2><ul><li>在线文档、协作表格、知识库。</li><li>CRM、ERP、OA、项目管理、工单系统。</li><li>邮箱、网盘、企业 IM、视频会议。</li><li>低代码平台、数据看板、在线设计工具。</li><li>云监控、日志分析、客服系统、营销自动化工具。</li></ul><p>这些产品通常只需要注册账号、购买套餐、配置组织或项目，就可以开始使用。</p><h2 id="saas-解决什么问题" tabindex="-1">SaaS 解决什么问题 <a class="header-anchor" href="#saas-解决什么问题" aria-label="Permalink to &quot;SaaS 解决什么问题&quot;">​</a></h2><ul><li><strong>降低使用门槛</strong>：不用自己部署服务器、数据库和运维系统。</li><li><strong>快速上线</strong>：购买后即可开通，适合快速验证业务。</li><li><strong>持续更新</strong>：功能升级、漏洞修复和兼容性维护由服务商完成。</li><li><strong>弹性付费</strong>：常见模式是按账号数、功能套餐、调用量或存储量计费。</li><li><strong>跨端访问</strong>：通常支持浏览器、移动端、桌面端和开放 API。</li></ul><h2 id="核心特点" tabindex="-1">核心特点 <a class="header-anchor" href="#核心特点" aria-label="Permalink to &quot;核心特点&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">特点</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">在线使用</td><td style="text-align:left;">通过网络访问，不依赖本地安装完整系统</td></tr><tr><td style="text-align:left;">多租户</td><td style="text-align:left;">多个客户共享同一套平台能力，但数据相互隔离</td></tr><tr><td style="text-align:left;">订阅付费</td><td style="text-align:left;">按月、按年、按席位或按用量付费</td></tr><tr><td style="text-align:left;">厂商维护</td><td style="text-align:left;">基础设施、版本升级、安全补丁由厂商负责</td></tr><tr><td style="text-align:left;">配置优先</td><td style="text-align:left;">通过配置适配业务，而不是每个客户单独开发一套</td></tr></tbody></table><h2 id="使用-saas-的基本流程" tabindex="-1">使用 SaaS 的基本流程 <a class="header-anchor" href="#使用-saas-的基本流程" aria-label="Permalink to &quot;使用 SaaS 的基本流程&quot;">​</a></h2><h3 id="_1-明确业务目标" tabindex="-1">1. 明确业务目标 <a class="header-anchor" href="#_1-明确业务目标" aria-label="Permalink to &quot;1. 明确业务目标&quot;">​</a></h3><p>先确认要解决的问题，例如：</p><ul><li>团队协作效率低。</li><li>客户跟进过程分散。</li><li>文档和文件缺少统一管理。</li><li>数据统计依赖手工表格。</li></ul><p>不要一开始就看功能列表，而是先明确核心流程和痛点。</p><h3 id="_2-选择合适产品" tabindex="-1">2. 选择合适产品 <a class="header-anchor" href="#_2-选择合适产品" aria-label="Permalink to &quot;2. 选择合适产品&quot;">​</a></h3><p>评估 SaaS 产品时可以关注：</p><ul><li>是否覆盖核心业务流程。</li><li>是否支持权限、审批、数据导入导出。</li><li>是否有 API、Webhook 或第三方集成能力。</li><li>数据是否支持备份和迁移。</li><li>服务可用性、安全合规和售后响应。</li><li>价格是否随团队规模增长而可接受。</li></ul><h3 id="_3-配置组织与权限" tabindex="-1">3. 配置组织与权限 <a class="header-anchor" href="#_3-配置组织与权限" aria-label="Permalink to &quot;3. 配置组织与权限&quot;">​</a></h3><p>常见配置包括：</p><ul><li>创建组织、部门、项目或空间。</li><li>添加成员并设置角色。</li><li>配置字段、表单、流程、通知规则。</li><li>接入 SSO、企业微信、飞书、钉钉等身份系统。</li></ul><p>权限设计要遵循最小权限原则：只给用户完成工作所需的权限。</p><h3 id="_4-迁移数据" tabindex="-1">4. 迁移数据 <a class="header-anchor" href="#_4-迁移数据" aria-label="Permalink to &quot;4. 迁移数据&quot;">​</a></h3><p>如果从旧系统切换到 SaaS，需要提前准备：</p><ul><li>清洗历史数据。</li><li>确认字段映射关系。</li><li>先小批量导入验证。</li><li>保留原系统备份。</li><li>约定切换时间，避免新旧系统并行产生混乱。</li></ul><h2 id="saas-的优点" tabindex="-1">SaaS 的优点 <a class="header-anchor" href="#saas-的优点" aria-label="Permalink to &quot;SaaS 的优点&quot;">​</a></h2><ul><li>上手快，前期成本低。</li><li>不需要自建完整技术团队维护软件。</li><li>能持续获得厂商的新功能和安全更新。</li><li>适合标准化程度较高的业务场景。</li><li>方便远程办公和跨团队协作。</li></ul><h2 id="saas-的风险" tabindex="-1">SaaS 的风险 <a class="header-anchor" href="#saas-的风险" aria-label="Permalink to &quot;SaaS 的风险&quot;">​</a></h2><ul><li><strong>数据依赖厂商</strong>：需要确认导出、备份和迁移能力。</li><li><strong>定制能力有限</strong>：复杂业务可能被产品边界限制。</li><li><strong>长期成本上升</strong>：账号数、用量增长后订阅费用可能变高。</li><li><strong>服务可用性依赖外部平台</strong>：厂商故障会影响业务使用。</li><li><strong>合规要求</strong>：敏感数据、客户数据和财务数据要关注存储位置与权限审计。</li></ul><h2 id="什么时候适合-saas" tabindex="-1">什么时候适合 SaaS <a class="header-anchor" href="#什么时候适合-saas" aria-label="Permalink to &quot;什么时候适合 SaaS&quot;">​</a></h2><p>适合选择 SaaS 的场景：</p><ul><li>业务流程比较通用，不需要大量定制。</li><li>希望快速启动，不想投入太多部署和运维成本。</li><li>团队规模在增长，需要统一工具和权限管理。</li><li>对功能迭代速度要求高，但内部研发资源有限。</li></ul><p>不太适合 SaaS 的场景：</p><ul><li>核心业务逻辑高度差异化。</li><li>数据不能放到第三方平台。</li><li>需要深度控制底层架构、网络和部署环境。</li><li>已有强研发团队并且自研收益明显更高。</li></ul><h2 id="和-iaas、paas-的区别" tabindex="-1">和 IaaS、PaaS 的区别 <a class="header-anchor" href="#和-iaas、paas-的区别" aria-label="Permalink to &quot;和 IaaS、PaaS 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">模型</th><th style="text-align:left;">你主要负责</th><th style="text-align:left;">服务商主要负责</th><th style="text-align:left;">典型例子</th></tr></thead><tbody><tr><td style="text-align:left;">IaaS</td><td style="text-align:left;">操作系统以上的部署、运维和应用</td><td style="text-align:left;">服务器、网络、存储等基础设施</td><td style="text-align:left;">云服务器 ECS、云硬盘、VPC</td></tr><tr><td style="text-align:left;">PaaS</td><td style="text-align:left;">应用代码、配置和业务逻辑</td><td style="text-align:left;">运行环境、中间件、扩缩容、发布能力</td><td style="text-align:left;">Serverless、云数据库、应用托管平台</td></tr><tr><td style="text-align:left;">SaaS</td><td style="text-align:left;">账号、配置、权限和业务使用</td><td style="text-align:left;">完整软件产品与底层技术</td><td style="text-align:left;">在线文档、CRM、项目管理系统</td></tr></tbody></table><p>越靠近 SaaS，用户需要维护的技术细节越少；越靠近 IaaS，用户拥有的控制权越高。</p><h2 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h2><ul><li>能用标准 SaaS 解决的问题，不要急着自研。</li><li>核心数据要确认导出能力，避免被单一厂商锁死。</li><li>先用小团队试点，再扩大到全公司。</li><li>关注权限、审计、备份、集成能力，而不是只看界面功能。</li><li>对关键业务系统，要准备降级方案或替代方案。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>SaaS 的价值是让团队把精力放在业务使用上，而不是软件安装、部署、升级和运维上。它适合快速使用成熟能力，但选型时要重点关注数据可控性、扩展能力和长期成本。</p>',40))])}const _=e(h,[["render",S]]);export{y as __pageData,_ as default};
